1	import { describe, it, expect, vi, beforeEach } from "vitest";
2	
3	// Apply creates the account (migration 00069).
4	//
5	// The public apply form used to insert an application for any typed email, with
6	// no proof the applicant controlled it and no account behind it. It is now two
7	// steps: startApplication validates the whole form and emails a code (or, for a
8	// signed-in applicant, submits at once), and confirmApplication checks the code
9	// and only then creates the account and the application. We pin:
10	//   start
11	//   - a new address must set a matching password of 8+ characters
12	//   - a new address gets a code: a verification row holding the chapter, the
13	//     email and the ENCRYPTED password, and NOTHING else is written
14	//   - an address that already has an account needs no password (row stores none)
15	//   - every form check (duplicate, CV, motivation, closed chapter, bot check)
16	//     refuses BEFORE a code is sent
17	//   - a failed code email deletes the row it just wrote
18	//   - a signed-in applicant submits at once, as their session's email and id,
19	//     whatever email the form carries
20	//   confirm
21	//   - wrong / expired / exhausted codes write no account and no application
22	//   - the right code creates the account from the RECORD's email and chapter
23	//     (the resubmitted form cannot redirect it), links user_id, deletes the code
24	//     and signs the new account in
25	//   - an existing account gets the application linked, and is NOT signed in
26	//   - a fixable form error does not consume the code
27	//   - failures after the claim hand the code back
28	//   - the team is derived from the account, never taken from the form
