84	import { startApplication, confirmApplication } from "@/lib/actions/applications";
85	
86	const CHAPTER_ID = "chapter-paris";
87	const OTHER_CHAPTER_ID = "chapter-other";
88	const EMAIL = "ada@example.com";
89	
90	type Op = "select" | "insert" | "update" | "upsert" | "delete";
91	type Call = {
92	  table: string;
93	  op: Op;
94	  payload: unknown;
95	  filters: Record<string, unknown>;
96	};
97	type Responder = (c: Call) => unknown;
98	
99	// Chainable Supabase mock in the style of tests/walk-in.test.ts. Every terminal
100	// call is recorded with its filters, so a test can tell the code CLAIM
101	// (verified_at set) from the RELEASE (verified_at back to null).
102	function makeAdminClient(responder: Responder, calls: Call[]) {
103	  return {
104	    from(table: string) {
105	      const call: Call = { table, op: "select", payload: null, filters: {} };
106	      const resolve = () => {
107	        calls.push(call);
108	        return Promise.resolve(responder(call) ?? { data: null, error: null });
109	      };
110	      const builder: Record<string, unknown> = {
111	        select: () => builder,
112	        insert: (p: unknown) => ((call.op = "insert"), (call.payload = p), builder),
113	        update: (p: unknown) => ((call.op = "update"), (call.payload = p), builder),
114	        upsert: (p: unknown) => ((call.op = "upsert"), (call.payload = p), builder),
115	        delete: () => ((call.op = "delete"), builder),
116	        eq: (k: string, v: unknown) => ((call.filters[k] = v), builder),
117	        is: (k: string, v: unknown) => ((call.filters[k] = v), builder),
118	        maybeSingle: resolve,
119	        single: resolve,
120	        then: (onF: (v: unknown) => unknown, onR?: (e: unknown) => unknown) =>
121	          resolve().then(onF, onR),
122	      };
123	      return builder;
124	    },
125	    auth: { admin: { createUser: mocks.createUser } },
126	  };
127	}
128	
129	const openChapter = (id = CHAPTER_ID, extra: Record<string, unknown> = {}) => ({
130	  id,
131	  name: id === CHAPTER_ID ? "Paris" : "Other",
132	  city: "Paris",
133	  country: "France",
134	  date: "2026-11-01",
135	  date_end: null,
136	  status: "applications_open",
137	  require_cv: false,
138	  require_motivation: false,
139	  ...extra,
140	});
141	
142	function verificationRecord(extra: Record<string, unknown> = {}) {
143	  return {
144	    id: "ver-1",
145	    email: EMAIL,
146	    code: "123456",
147	    type: "application_registration",
148	    attempts: 0,
149	    expires_at: new Date(Date.now() + 10 * 60 * 1000).toISOString(),
150	    verified_at: null,
151	    metadata: { chapterId: CHAPTER_ID, email: EMAIL, password: "enc(hunter22)" },
152	    ...extra,
153	  };
154	}
