156	interface World {
157	  chapters?: Record<string, Record<string, unknown>>;
158	  profile?: { id: string } | null;
159	  duplicate?: boolean;
160	  record?: Record<string, unknown> | null;
161	  claimWins?: boolean;
162	  insertError?: { code: string } | null;
163	  verificationInsertError?: boolean;
164	}
