begin;
-- a chapter to hang rows on
select id as ch from chapters limit 1 \gset
-- 1. application first, account later (profile-side trigger), mixed case
insert into applications (chapter_id,email,first_name,last_name,form_data) values (:'ch','Late.Person@Example.com','L','P','{}');
insert into auth.users (id, email, instance_id, aud, role) values ('11111111-1111-1111-1111-111111111111','late.person@example.com','00000000-0000-0000-0000-000000000000','authenticated','authenticated');
select 'profile-side link', user_id = '11111111-1111-1111-1111-111111111111' from applications where email='Late.Person@Example.com';
-- 2. account first, application later (application-side trigger)
insert into applications (chapter_id,email,first_name,last_name,form_data) values (:'ch','late.person@example.com','L','P','{}');
select 'app-side link', user_id = '11111111-1111-1111-1111-111111111111' from applications where email='late.person@example.com';
-- 3. explicit user_id is never overwritten
insert into auth.users (id, email, instance_id, aud, role) values ('22222222-2222-2222-2222-222222222222','other@example.com','00000000-0000-0000-0000-000000000000','authenticated','authenticated');
insert into applications (chapter_id,email,first_name,last_name,form_data,user_id) values (:'ch','other@example.com','O','X','{}','11111111-1111-1111-1111-111111111111');
select 'explicit kept', user_id = '11111111-1111-1111-1111-111111111111' from applications where email='other@example.com';
-- 4. ambiguous profiles (case variants) -> no link
insert into profiles (id,email,name) values ('33333333-3333-3333-3333-333333333333','Twin@example.com','a');
insert into profiles (id,email,name) values ('44444444-4444-4444-4444-444444444444','twin@example.com','b');
update applications set user_id = null where false;
insert into applications (chapter_id,email,first_name,last_name,form_data) values (:'ch','TWIN@example.com','T','W','{}');
select 'ambiguous unlinked', user_id is null from applications where email='TWIN@example.com';
-- 5. deleting the account keeps the application (ON DELETE SET NULL)
delete from auth.users where id='22222222-2222-2222-2222-222222222222';
delete from profiles where id='11111111-1111-1111-1111-111111111111';
select 'kept after delete', count(*) = 3 and bool_and(user_id is null) from applications where email in ('Late.Person@Example.com','late.person@example.com','other@example.com');
-- 6. the new verification type is accepted, an unknown one is not
insert into verification_codes (email,code,type,expires_at) values ('x@example.com','123456','application_registration',now()+interval '1 minute');
select 'new type ok', true;
savepoint s;
insert into verification_codes (email,code,type,expires_at) values ('x@example.com','123456','bogus',now());
SQL

