-- 5. deleting the account keeps the application (ON DELETE SET NULL)
insert into auth.users (id, email, instance_id, aud, role) values ('55555555-5555-5555-5555-555555555555','gone@example.com','00000000-0000-0000-0000-000000000000','authenticated','authenticated');
