python3 - <<'EOF'
p="supabase/migrations/00069_application_user_link_and_registration.sql"
s=open(p).read()
old='''-- Application side: fill user_id on insert (and on an email correction) from the
-- matching profile. Never overwrites a user_id the caller already set.
create or replace function public.link_application_to_profile()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  match_id uuid;
  match_count int;
begin
  if new.user_id is null and new.email is not null then
    select min(p.id::text)::uuid, count(*) into match_id, match_count
    from public.profiles p
    where lower(p.email) = lower(new.email);
    -- Link only an unambiguous match.
    if match_count = 1 then
      new.user_id := match_id;
    end if;
  end if;
  return new;
end;
$$;'''
new='''-- Application side: on insert, fill user_id from the matching profile (a
-- user_id the caller set is kept). On an email CHANGE, recompute it from the new
-- address: keeping the old link would leave the row owned by one account while
-- the email-based read policy shows it to another.
create or replace function public.link_application_to_profile()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  match_id uuid;
  match_count int;
begin
  if tg_op = 'UPDATE' then
    if new.email is not distinct from old.email then
      return new;
    end if;
    new.user_id := null;
  end if;

  if new.user_id is null and new.email is not null then
    select min(p.id::text)::uuid, count(*) into match_id, match_count
    from public.profiles p
    where lower(p.email) = lower(new.email);
    -- Link only an unambiguous match.
    if match_count = 1 then
      new.user_id := match_id;
    end if;
  end if;
  return new;
end;
$$;'''
assert old in s
s=s.replace(old,new)
open(p,"w").write(s)
EOF
echo ok

