331:export async function confirmApplication(formData: FormData): Promise<ApplyResult> {
332:  const verificationId = (formData.get("verificationId") as string) ?? "";
333:  const code = ((formData.get("code") as string) ?? "").trim();
334:  const firstName = (formData.get("firstName") as string)?.trim();
335:  const lastName = (formData.get("lastName") as string)?.trim();
336:
337:  if (!verificationId || !code) {
338:    return { error: "Please enter the code from your email." };
339:  }
340:  if (!firstName || !lastName) {
341:    return { error: "First name, last name, and email are required." };
342:  }
343:
344:  const adminClient = createAdminClient();
345:
346:  const { data: record } = await adminClient
347:    .from("verification_codes")
348:    .select("*")
349:    .eq("id", verificationId)
350:    .eq("type", "application_registration")
351:    .is("verified_at", null)
352:    .maybeSingle();
353:
354:  if (!record) {
355:    return { error: "This code is no longer valid. Please submit the form again." };
356:  }
357:  if (new Date(record.expires_at as string) < new Date()) {
358:    return { error: "Your code expired. Please submit the form again." };
359:  }
360:  const attempts = (record.attempts as number) ?? 0;
361:  if (attempts >= APPLICATION_CODE_MAX_ATTEMPTS) {
362:    return { error: "Too many failed attempts. Please submit the form again." };
363:  }
364:  if (record.code !== code) {
365:    await adminClient
366:      .from("verification_codes")
367:      .update({ attempts: attempts + 1 })
368:      .eq("id", verificationId);
369:    const remaining = APPLICATION_CODE_MAX_ATTEMPTS - 1 - attempts;
370:    return {
371:      error:
372:        remaining > 0
373:          ? `Incorrect code. ${remaining} attempt${remaining === 1 ? "" : "s"} remaining.`
374:          : "Incorrect code. Please submit the form again.",
375:    };
376:  }
377:
378:  const meta = record.metadata as {
379:    chapterId: string;
380:    email: string;
381:    password: string | null;
382:  };
383:  const email = (record.email as string).trim().toLowerCase();
384:
385:  // Re-validate the resubmitted form BEFORE claiming the code, so a fixable
386:  // mistake (a missing field, a closed chapter message) does not burn it.
387:  const chapter = await loadOpenChapter(adminClient, meta.chapterId);
388:  if (!chapter) {
389:    return { error: "Applications are not currently open for this match." };
390:  }
391:  const valid = await validateApplicationForm(adminClient, formData, chapter, email);
392:  if ("error" in valid) return valid;
393:
394:  // Atomically claim the code: of two concurrent confirms (double click, two
395:  // tabs) only one proceeds.
396:  const { data: claimed } = await adminClient
397:    .from("verification_codes")
398:    .update({ verified_at: new Date().toISOString() })
399:    .eq("id", verificationId)
400:    .is("verified_at", null)
401:    .select("id")
402:    .maybeSingle();
403:  if (!claimed) {
404:    return { error: "This code was already used. Please log in to see your application." };
405:  }
406:  // Hand the code back if anything below fails, so the applicant can retry with
407:  // the same code instead of starting over.
408:  const releaseClaim = () =>
409:    adminClient
410:      .from("verification_codes")
411:      .update({ verified_at: null })
412:      .eq("id", verificationId);
413:
414:  // Resolve the account. The profile is looked up again rather than trusting
415:  // step one: the applicant may have registered in another tab since.
416:  let userId: string;
417:  let createdAccount = false;
418:  const { data: existingProfile } = await adminClient
419:    .from("profiles")
420:    .select("id")
421:    .eq("email", email)
422:    .maybeSingle();
423:
424:  if (existingProfile) {
425:    userId = existingProfile.id as string;
426:  } else if (meta.password) {
427:    const { data: authData, error: authError } = await adminClient.auth.admin.createUser({
428:      email,
429:      password: decryptPassword(meta.password),
430:      email_confirm: true,
431:      user_metadata: { name: `${firstName} ${lastName}` },
432:    });
433:    if (authError || !authData.user) {
434:      await releaseClaim();
435:      console.error("Application account creation error:", authError);
436:      return { error: "We could not create your account. Please try again." };
437:    }
438:    userId = authData.user.id;
439:    createdAccount = true;
440:    // The 00055 trigger creates the profile; this sets the name and role the
441:    // way every registration path does.
442:    await adminClient.from("profiles").upsert({
443:      id: userId,
444:      email,
445:      name: `${firstName} ${lastName}`,
446:      role: "participant",
447:    });
