set -a && . ./.env.supabase && set +a && run(){ curl -s -X POST "https://api.supabase.com/v1/projects/${SUPABASE_PROD_REF}/database/query/read-only" -H "Authorization: Bearer $SUPABASE_ACCESS_TOKEN" -H "Content-Type: application/json" -d "$(jq -n --arg q "$1" '{query: $q}')"; }; P="with people as (select p.id, p.name, t.id as team_id, t.name as team, tm.joined_at from profiles p join team_members tm on tm.user_id=p.id join teams t on t.id=tm.team_id where (p.name, t.name) in (('Ahlem Trabelsi','Harissa'),('Victor Bonilla','AskOnce'),('Gregor Waxenecker','Codacabana')))";
echo "== account + memberships:"; run "$P select pe.name, pe.team, to_char(pr.created_at at time zone 'Europe/Berlin','YYYY-MM-DD') as account_created, (select string_agg(t2.name||' (joined '||to_char(tm2.joined_at,'YYYY-MM-DD')||')', ', ') from team_members tm2 join teams t2 on t2.id=tm2.team_id where tm2.user_id=pe.id) as all_current_teams from people pe join profiles pr on pr.id=pe.id" | jq -r '.[] | [.name,.team,.account_created,.all_current_teams] | @tsv' | column -t -s $'\t';
echo "== applications (team they applied with):"; run "$P select pe.name, c.name as chapter, a.status, to_char(a.created_at,'YYYY-MM-DD') as applied, coalesce(t3.name,'-') as applied_with_team, (a.existing_team_id = pe.team_id) as same_team from people pe join applications a on a.user_id=pe.id or lower(a.email)=lower((select email from profiles where id=pe.id)) join chapters c on c.id=a.chapter_id left join teams t3 on t3.id=a.existing_team_id order by pe.name, a.created_at" | jq -r '.[] | [.name,.chapter,.status,.applied,.applied_with_team,.same_team] | @tsv' | column -t -s $'\t';
echo "== join requests to that team:"; run "$P select pe.name, jr.status, to_char(jr.created_at,'YYYY-MM-DD') as requested from people pe join team_join_requests jr on jr.team_id=pe.team_id and jr.user_id=pe.id" | jq -r '.[] | [.name,.status,.requested] | @tsv' | column -t -s $'\t';
echo "== event log touching person+team:"; run "$P select pe.name, to_char(e.created_at at time zone 'Europe/Berlin','YYYY-MM-DD HH24:MI') as at, e.action from people pe join event_log e on (e.actor_id=pe.id or e.entity_id=pe.id::text or e.delta::text like '%'||pe.id::text||'%') and (e.entity_id=pe.team_id::text or e.delta::text like '%'||pe.team_id::text||'%') order by pe.name, e.created_at" | jq -r '.[] | [.name,.at,.action] | @tsv' | column -t -s $'\t'

