/**
 * One-off: send the Grand Finale invite to SPECIFIC people only.
 *
 * Same row + same email as sendFinaleInvites() (lib/actions/finale-invites.ts),
 * but limited to the emails listed below instead of every uninvited member of
 * every qualifying team. Local only (.claude/ is gitignored), never committed.
 *
 *   pnpm exec tsx .claude/finale-targeted/send-finale-invites-to.ts          # dry run
 *   pnpm exec tsx .claude/finale-targeted/send-finale-invites-to.ts --send   # send
 */
import { config } from "dotenv";
config({ path: ".env.local" });

import { createClient } from "@supabase/supabase-js";
import { renderFinaleInviteEmail } from "@/lib/emails/render";
import { sendEmail } from "@/lib/email";
import { FINALE_INVITE_MAX_RANK, FINALE_INVITE_SUBJECT } from "@/lib/finale";

const TARGET_EMAILS = ["ahlemtrabelsi087@gmail.com", "amine.cheikhrouhou54@gmail.com"];
const SEND = process.argv.includes("--send");

const db = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!,
  { auth: { persistSession: false } }
);

function firstNameOf(fullName: string, email: string): string {
  return fullName.trim().split(/\s+/)[0] || email.split("@")[0];
}

async function main() {
  console.log(`Mode: ${SEND ? "SEND" : "DRY RUN"}  |  site: ${process.env.NEXT_PUBLIC_SITE_URL}`);

  const { data: finale } = await db
    .from("chapters")
    .select("id, name, status, is_finale")
    .eq("is_finale", true)
    .single();
  if (!finale) throw new Error("No Grand Finale chapter.");
  if (finale.status === "draft" || finale.status === "completed") {
    throw new Error(`Finale is ${finale.status}; the invite action would refuse.`);
  }

  const { data: qualifying } = await db
    .from("leaderboard")
    .select("team_id, team_name, rank")
    .lte("rank", FINALE_INVITE_MAX_RANK);
  const qualifyingTeams = new Map((qualifying ?? []).map((t) => [t.team_id as string, t]));

  const plan: Array<{ userId: string; email: string; name: string; teamId: string; teamName: string }> = [];
  for (const email of TARGET_EMAILS) {
    const { data: profile } = await db
      .from("profiles")
      .select("id, name, email")
      .eq("email", email)
      .single();
    if (!profile) throw new Error(`No account for ${email}`);

    const { data: memberships } = await db
      .from("team_members")
      .select("team_id")
      .eq("user_id", profile.id);
    const team = (memberships ?? [])
      .map((m) => qualifyingTeams.get(m.team_id as string))
      .find(Boolean);
    if (!team) throw new Error(`${email} is not on a qualifying team.`);

    const { data: existing } = await db
      .from("finale_invites")
      .select("id")
      .eq("chapter_id", finale.id)
      .eq("user_id", profile.id)
      .maybeSingle();
    if (existing) throw new Error(`${email} already has a Finale invite.`);

    plan.push({
      userId: profile.id as string,
      email,
      name: (profile.name as string) ?? "",
      teamId: team.team_id as string,
      teamName: team.team_name as string,
    });
  }

  console.log(`Finale: ${finale.name} (${finale.status})`);
  for (const p of plan) {
    console.log(`  -> ${p.name} <${p.email}>  team ${p.teamName} (rank ${qualifyingTeams.get(p.teamId)!.rank})`);
  }
  console.log(`Subject: ${FINALE_INVITE_SUBJECT}`);
  if (!SEND) {
    console.log("Dry run: nothing written, nothing sent. Re-run with --send.");
    return;
  }

  let sent = 0;
  for (const p of plan) {
    const { data: inserted, error } = await db
      .from("finale_invites")
      .insert({ chapter_id: finale.id, team_id: p.teamId, user_id: p.userId, email: p.email })
      .select("invite_token")
      .single();
    if (error || !inserted) {
      console.error(`FAILED to record invite for ${p.email}:`, error?.message);
      continue;
    }
    try {
      const html = await renderFinaleInviteEmail({
        firstName: firstNameOf(p.name, p.email),
        teamName: p.teamName,
        inviteToken: inserted.invite_token as string,
      });
      await sendEmail({ to: p.email, subject: FINALE_INVITE_SUBJECT, html, skipRateLimit: true });
      sent++;
      console.log(`SENT to ${p.email}`);
    } catch (err) {
      // Same rollback as the action: nobody is marked invited without an email.
      await db.from("finale_invites").delete().eq("chapter_id", finale.id).eq("user_id", p.userId);
      console.error(`FAILED to send to ${p.email} (invite row removed):`, err);
    }
  }

  if (sent > 0) {
    await db.from("event_log").insert({
      action: "finale.invites_sent",
      entity_type: "chapter",
      entity_id: finale.id,
      actor_type: "admin",
      delta: { finale_invites: { sent, failed: plan.length - sent, skipped: 0, targeted: true } },
    });
  }
  console.log(`Done: ${sent}/${plan.length} sent.`);
}

main().catch((e) => {
  console.error(e.message ?? e);
  process.exit(1);
});

