input.content:
/**
 * One-off: RESEND the acceptance email (with the check-in QR) for one application.
 *
 * The app's sendAcceptanceEmailForApplication() refuses once acceptance_email_sent_at
 * is set, so this calls the shared deliverAcceptanceEmail() directly: the same
 * email, QR and per-chapter custom text the admin bulk send produces. The QR is the
 * application's existing check_in_token, so an earlier copy stays valid too.
 * Local only (.claude/ is gitignored), never committed.
 *
 *   pnpm exec dotenv -e .env.local -- tsx .claude/finale-targeted/resend-acceptance.ts <email> [chapter-name]          # dry run
 *   pnpm exec dotenv -e .env.local -- tsx .claude/finale-targeted/resend-acceptance.ts <email> [chapter-name] --send   # send
 */
import { createClient } from "@supabase/supabase-js";
import { deliverAcceptanceEmail, type AcceptanceEmailApplication } from "@/lib/acceptance-email";
import { getChapterCommunications } from "@/lib/queries";
import { acceptanceEmailSubject } from "@/lib/communications";
import { logEventStrict } from "@/lib/event-log";

const args = process.argv.slice(2).filter((a) => !a.startsWith("--"));
const EMAIL = (args[0] ?? "").trim().toLowerCase();
const CHAPTER = args[1] ?? "Grand Finale";
const SEND = process.argv.includes("--send");
if (!EMAIL) throw new Error("Pass the recipient email.");

const db = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!,
  { auth: { persistSession: false } }
);

async function main() {
  console.log(`Mode: ${SEND ? "SEND" : "DRY RUN"}`);
  const { data: rows, error } = await db
    .from("applications")
    .select(
      "id, email, first_name, last_name, status, check_in_token, acceptance_email_sent_at, chapter_id, chapters!inner(name, city, country, date, date_end, slug)"
    )
    .eq("email", EMAIL)
    .eq("chapters.name", CHAPTER);
  if (error) throw new Error(error.message);
  if (!rows || rows.length !== 1) throw new Error(`Expected exactly 1 ${CHAPTER} application for ${EMAIL}, found ${rows?.length ?? 0}.`);
  const app = rows[0];
  if (app.status !== "accepted" && app.status !== "checked_in") {
    throw new Error(`Application status is ${app.status}; only accepted applicants get this email.`);
  }
  if (!app.check_in_token) throw new Error("Application has no check-in token.");

  const chapter = (Array.isArray(app.chapters) ? app.chapters[0] : app.chapters) as AcceptanceEmailApplication["chapters"];
  const comms = await getChapterCommunications(app.chapter_id as string);

  console.log(`To:       ${app.first_name} ${app.last_name} <${app.email}>`);
  console.log(`Match:    ${chapter.name} (status ${app.status})`);
  console.log(`Subject:  ${acceptanceEmailSubject(comms.acceptanceEmailSubject, chapter.name)}`);
  console.log(`QR token: ${String(app.check_in_token).slice(0, 8)}... (unchanged)`);
  console.log(`Previously sent: ${app.acceptance_email_sent_at ?? "never"}`);
  if (!SEND) {
    console.log("Dry run: nothing sent. Re-run with --send.");
    return;
  }

  await deliverAcceptanceEmail(
    {
      id: app.id as string,
      email: app.email as string,
      first_name: app.first_name as string,
      check_in_token: app.check_in_token as string,
      chapters: chapter,
    },
    comms
  );
  console.log(`SENT to ${app.email}`);

  await logEventStrict({
    action: "application.acceptance_email_resent",
    entityType: "application",
    entityId: app.id as string,
    actorType: "system",
    delta: { resent: { email: app.email, chapter_id: app.chapter_id } },
    metadata: { note: "Manual resend of the acceptance email (script in .claude/finale-targeted)" },
  });
}

main().catch((e) => {
  console.error(e.message ?? e);
  process.exit(1);
});

