  const { data: existing } = await adminClient
    .from("admin_emails")
    .select("id")
    .eq("email", normalized)
    .single();

  if (existing) {
    return { error: "This email is already on the admin allowlist." };
  }

  const { error } = await adminClient
    .from("admin_emails")
    .insert({ email: normalized, added_by: user.id });

  if (error) {
    return { error: error.message };
  }

  // Pre-provision auth user so Google OAuth login works
  // (Supabase has signups disabled; without this, first OAuth login fails with signup_disabled)
  const { data: existingProfile } = await adminClient
    .from("profiles")
    .select("id")
    .eq("email", normalized)
    .single();

  if (!existingProfile) {
    const { data: authUser } = await adminClient.auth.admin.createUser({
      email: normalized,
      email_confirm: true,
      user_metadata: { name: normalized.split("@")[0] },
    });

    if (authUser?.user) {
      await adminClient.from("profiles").insert({
        id: authUser.user.id,
        email: normalized,
        name: normalized.split("@")[0],
        role: "admin",
      });
    }
  }

