cat > .claude/finale-targeted/set-verified-repo.ts <<'EOF'
// One-off: give a manually written submission the verified repository version
// (repo_snapshots) that the normal submit path stores, using the app's own
// prepareSubmissionRepositories(). Saving it with a fresh updated_at re-fires the
// enqueue trigger, so the background worker copies the repo with valid input.
import { createClient } from "@supabase/supabase-js";
import { prepareSubmissionRepositories } from "@/lib/submission-snapshots/prepare";

const [teamId, challengeId] = process.argv.slice(2);
const db = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.SUPABASE_SERVICE_ROLE_KEY!, { auth: { persistSession: false } });

async function main() {
  const { data: sub } = await db.from("submissions").select("id, fields, repo_snapshots, submission_revision").eq("team_id", teamId).eq("challenge_id", challengeId).single();
  if (!sub) throw new Error("submission not found");
  const { data: ch } = await db.from("challenges").select("submission_fields, entire_required").eq("id", challengeId).single();
  if (!ch) throw new Error("challenge not found");
  const selections = await prepareSubmissionRepositories(sub.fields as Record<string, string>, {
    submission_fields: ch.submission_fields, entire_required: ch.entire_required,
  } as never);
  console.log("verified version:", JSON.stringify(selections));
  const { error } = await db.from("submissions").update({
    repo_snapshots: selections,
    submission_revision: Math.max(1, (sub.submission_revision as number) ?? 0),
    updated_at: new Date().toISOString(),
  }).eq("id", sub.id);
  if (error) throw new Error(error.message);
  console.log("saved; copy job re-queued by trigger");
}
main().catch((e) => { console.error(e.message ?? e); process.exit(1); });
EOF
