grep -ln "on challenge_registrations\|on public.challenge_registrations" supabase/migrations/*.sql | xargs grep -h "create trigger" 2>/dev/null | head -3; cat > .claude/finale-targeted/move-challenge.ts <<'EOF'
// One-off: move undeterministic tornado's Finale registration + submission from
// BMW's challenge to Tacto Negotation Arena, keeping the SUBMITTED commit and the
// last pre-deadline Entire checkpoint. Does not touch fields/updated_at, so the
// enqueue trigger does not fire: the jury copy and the completed review are kept.
import { createClient } from "@supabase/supabase-js";
import { writeFileSync } from "fs";
const db = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.SUPABASE_SERVICE_ROLE_KEY!, { auth: { persistSession: false } });
const TEAM = "undeterministic tornado", FROM = "AI for Product Decision Making", TO = "Tacto Negotation Arena";
const SUBMITTED_SHA = "10c803697531261146de659d5a28f01444a3572e";
const CHECKPOINT = { ref: "refs/heads/entire/checkpoints/v1", sha: "7b8c946a8c746c972333b3342e40781db947ea32" };

async function main() {
  const { data: team } = await db.from("teams").select("id").eq("name", TEAM).single();
  const { data: finale } = await db.from("chapters").select("id").eq("is_finale", true).single();
  const { data: chs } = await db.from("challenges").select("id, title").eq("chapter_id", finale!.id).in("title", [FROM, TO]);
  const from = chs!.find((c) => c.title === FROM)!.id, to = chs!.find((c) => c.title === TO)!.id;
  const { data: reg } = await db.from("challenge_registrations").select("*").eq("team_id", team!.id).eq("challenge_id", from).single();
  const { data: sub } = await db.from("submissions").select("id, challenge_id, repo_snapshots").eq("team_id", team!.id).eq("challenge_id", from).single();
  if (!reg || !sub) throw new Error("registration or submission not found on the BMW challenge");
  const old = sub.repo_snapshots as Record<string, Record<string, unknown>>;
  if (old.repo.frozen_sha !== SUBMITTED_SHA) throw new Error("submitted commit changed; aborting");
  writeFileSync(".claude/finale-targeted/move-challenge.rollback.json", JSON.stringify({ reg, sub, from, to }, null, 2));

  const newSnap = { ...old, repo: { ...old.repo, entire_required: true, checkpoint_manifest: [CHECKPOINT] } };
  const r1 = await db.from("challenge_registrations").update({ challenge_id: to }).eq("id", reg.id);
  if (r1.error) throw new Error("registration: " + r1.error.message);
  const r2 = await db.from("submissions").update({ challenge_id: to, repo_snapshots: newSnap }).eq("id", sub.id);
  if (r2.error) {
    await db.from("challenge_registrations").update({ challenge_id: from }).eq("id", reg.id);
    throw new Error("submission (registration rolled back): " + r2.error.message);
  }
  console.log("moved registration + submission", { submission: sub.id, from: FROM, to: TO });
}
main().catch((e) => { console.error(e.message ?? e); process.exit(1); });
EOF
