// One-off: re-run the AI code review for ONE submission, exactly like the admin
// console's Queue route (app/api/admin/code-reviews/queue): upsert the row back
// to queued with cleared progress, then dispatch the review worker workflow.
import { createClient } from "@supabase/supabase-js";
import { dispatchCodeReviewWorker } from "@/lib/code-review/dispatch";

const [submissionId] = process.argv.slice(2);
const db = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.SUPABASE_SERVICE_ROLE_KEY!, { auth: { persistSession: false } });

async function main() {
  const { error } = await db.from("code_reviews").upsert(
    { submission_id: submissionId, status: "queued", review_version: 2, queued_at: new Date().toISOString(), progress: null },
    { onConflict: "submission_id" }
  );
  if (error) throw new Error(error.message);
  console.log("review queued");
  const result = await dispatchCodeReviewWorker();
  console.log("dispatch:", result.ok ? "ok" : `NOT ok (${"reason" in result ? result.reason : "?"}): ${result.message}`);
}
main().catch((e) => { console.error(e.message ?? e); process.exit(1); });

