/**
 * One-off: give every Grand Finale team that SUBMITTED but has no score a
 * "Participation, +2" score, exactly like the admin Scores-page override
 * (app/api/admin/scores/override) followed by Publish:
 *   source admin_override, placement null, points PARTICIPATION_POINTS,
 *   challenge_id/challenge_name of the challenge they submitted to,
 *   published true + published_at.
 * Never touches a team that already has a score (the 9 podium entries).
 * One score.overridden event per team, as the route logs. Local only.
 *
 *   pnpm exec dotenv -e .env.local -- tsx .claude/finale-targeted/participation-scores.ts          # list only
 *   pnpm exec dotenv -e .env.local -- tsx .claude/finale-targeted/participation-scores.ts --apply  # write
 */
import { createClient } from "@supabase/supabase-js";
import { PARTICIPATION_POINTS } from "@/lib/scoring";
import { logEventStrict } from "@/lib/event-log";

const APPLY = process.argv.includes("--apply");
const db = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.SUPABASE_SERVICE_ROLE_KEY!, { auth: { persistSession: false } });

async function main() {
  const { data: finale } = await db.from("chapters").select("id, status").eq("is_finale", true).single();
  if (!finale) throw new Error("no finale");
  const { data: challenges } = await db.from("challenges").select("id, title").eq("chapter_id", finale.id);
  const titles = new Map((challenges ?? []).map((c) => [c.id as string, c.title as string]));
  const { data: subs } = await db.from("submissions").select("team_id, challenge_id, teams(name)").in("challenge_id", [...titles.keys()]);
  const { data: scores } = await db.from("scores").select("team_id").eq("chapter_id", finale.id);
  const scored = new Set((scores ?? []).map((s) => s.team_id as string));

  const byTeam = new Map<string, { teamId: string; team: string; challengeId: string }>();
  for (const s of subs ?? []) {
    const teamId = s.team_id as string;
    if (scored.has(teamId)) continue;
    if (byTeam.has(teamId)) throw new Error(`team ${teamId} has two Finale submissions; decide manually`);
    const team = (Array.isArray(s.teams) ? s.teams[0] : s.teams) as { name: string } | null;
    byTeam.set(teamId, { teamId, team: team?.name ?? "?", challengeId: s.challenge_id as string });
  }
  const rows = [...byTeam.values()].sort((a, b) =>
    (titles.get(a.challengeId)! + a.team).localeCompare(titles.get(b.challengeId)! + b.team));

  console.log(`Finale status: ${finale.status} | already scored: ${scored.size} | to add: ${rows.length} x Participation +${PARTICIPATION_POINTS}`);
  let last = "";
  for (const r of rows) {
    const t = titles.get(r.challengeId)!;
    if (t !== last) { console.log(`\n${t}`); last = t; }
    console.log(`  - ${r.team}`);
  }
  if (!APPLY) { console.log("\nList only: nothing written. Re-run with --apply."); return; }

  const now = new Date().toISOString();
  let written = 0;
  for (const r of rows) {
    const challengeName = titles.get(r.challengeId)!;
    const { error } = await db.from("scores").insert({
      chapter_id: finale.id, team_id: r.teamId, placement: null, points: PARTICIPATION_POINTS,
      source: "admin_override", challenge_id: r.challengeId, challenge_name: challengeName,
      published: true, published_at: now,
    });
    if (error) { console.error(`FAILED ${r.team}: ${error.message}`); continue; }
    written++;
    await logEventStrict({
      action: "score.overridden", entityType: "score", entityId: finale.id as string, actorType: "system",
      delta: { team_id: r.teamId, placement: { to: null }, points: { to: PARTICIPATION_POINTS },
        challenge_id: { to: r.challengeId }, challenge_name: { to: challengeName } },
      metadata: { note: "Finale participation backfill (no jury finalize ran); script in .claude/finale-targeted" },
    });
  }
  console.log(`\nWritten: ${written}/${rows.length} participation scores (published).`);
}
main().catch((e) => { console.error(e.message ?? e); process.exit(1); });

