/**
 * One-off: send the Grand Finale certificate email ONLY to members of the teams
 * that got the participation backfill (Finale scores with placement null,
 * points 2, source admin_override). Same email, subject, links and tokens as
 * sendCertificateEmails() in lib/actions/admin.ts, so the podium teams who
 * already received theirs are not mailed again. Non-placed => the email's link
 * is the PARTICIPATION variant (resultLabel "Participant", no extra link).
 * Local only (.claude/ is gitignored).
 *
 *   pnpm exec dotenv -e .env.local -- tsx .claude/finale-targeted/send-participation-certificates.ts          # preview
 *   pnpm exec dotenv -e .env.local -- tsx .claude/finale-targeted/send-participation-certificates.ts --send   # send
 */
import { createClient } from "@supabase/supabase-js";
import { renderCertificateEmail } from "@/lib/emails/render";
import { sendEmail } from "@/lib/email";
import { formatDate, runWithConcurrency } from "@/lib/utils";
import { isPlacedPlacement } from "@/lib/scoring";
import { certificateTokenV2 } from "@/lib/certificate-token";
import { logEventStrict } from "@/lib/event-log";

const SEND = process.argv.includes("--send");
const db = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.SUPABASE_SERVICE_ROLE_KEY!, { auth: { persistSession: false } });

async function main() {
  const { data: chapter } = await db.from("chapters").select("id, name, city, country, date, date_end, status").eq("is_finale", true).single();
  if (!chapter) throw new Error("no finale");
  if (chapter.status !== "completed") throw new Error("Finale is not completed (scores not published).");

  const { data: scores } = await db.from("scores")
    .select("team_id, placement, points, published, source")
    .eq("chapter_id", chapter.id).eq("published", true).is("placement", null).eq("source", "admin_override");
  const targets = (scores ?? []).filter((s) => !isPlacedPlacement(s.placement as number | null));
  if (targets.length !== 49) throw new Error(`Expected the 49 participation teams, found ${targets.length}. Aborting.`);

  const baseUrl = process.env.NEXT_PUBLIC_SITE_URL || "https://ehl.gg";
  const chapterDate = chapter.date
    ? chapter.date_end ? `${formatDate(chapter.date)} - ${formatDate(chapter.date_end)}` : formatDate(chapter.date)
    : "";
  const chapterCity = `${chapter.city}, ${chapter.country}`;
  const subject = `Your EHL Certificates: ${chapter.name}`;

  const jobs: Array<{ email: string; name: string; team: string; url: string }> = [];
  let missingProfile = 0;
  for (const s of targets) {
    const teamId = s.team_id as string;
